import{_ as s,o as t,c as r,ah as n}from"./chunks/framework.C-FRNfAJ.js";const m=JSON.parse('{"title":"Réglages","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/administrateur/reglages.md","filePath":"src/guide/administrateur/reglages.md"}'),a={name:"guide/administrateur/reglages.md"};function o(i,e,l,u,d,g){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="reglages" tabindex="-1">Réglages <a class="header-anchor" href="#reglages" aria-label="Permalink to &quot;Réglages&quot;">​</a></h1><p><strong>Administration → Réglages</strong> regroupe les paramètres généraux de l&#39;application. Ils s&#39;appliquent à tout ce que Kura produit ensuite : conventions, factures, certificats.</p><h2 id="les-conventions-et-les-mentions-legales" tabindex="-1">Les conventions et les mentions légales <a class="header-anchor" href="#les-conventions-et-les-mentions-legales" aria-label="Permalink to &quot;Les conventions et les mentions légales&quot;">​</a></h2><ul><li><strong>Contre-signature des conventions</strong> : <strong>Automatique, au nom du représentant</strong> (par défaut), ou <strong>Par le Coordinateur pédagogique</strong>. Le même réglage vaut pour la convention de formation, la tripartite, la convention de stage et le contrat de partenariat. En mode manuel, c&#39;est le Coordinateur qui les contre-signe, ou un Chargé de partenariats pour un partenariat.</li><li><strong>Représentant d&#39;edPage group</strong>, au nom duquel se fait la contre-signature automatique.</li><li><strong>Adresse du siège</strong>, <strong>RCCM</strong> et <strong>NIF</strong> : imprimés sur les documents.</li></ul><h2 id="les-factures" tabindex="-1">Les factures <a class="header-anchor" href="#les-factures" aria-label="Permalink to &quot;Les factures&quot;">​</a></h2><ul><li><strong>Mention de TVA</strong> : la mention d&#39;exonération imprimée sur chaque facture (les montants sont hors taxe).</li><li><strong>Modalités de paiement</strong> : numéros Mobile Money, RIB et autres, imprimés sur chaque facture et affichés à l&#39;apprenant.</li><li><strong>Forfait de mise en relation</strong> et <strong>forfait d&#39;accompagnement</strong> (FCFA, par profil retenu). <strong>Tant que ces forfaits ne sont pas fixés, la confirmation d&#39;une mise en relation est impossible.</strong> Voir <a href="./../entreprises/recrutement.html">Recruter des profils certifiés</a>.</li></ul><h2 id="les-mentions-du-certificat" tabindex="-1">Les mentions du certificat <a class="header-anchor" href="#les-mentions-du-certificat" aria-label="Permalink to &quot;Les mentions du certificat&quot;">​</a></h2><p>Les seuils, en moyenne sur 20, à partir desquels un certificat porte la mention <strong>Assez bien</strong>, <strong>Bien</strong> ou <strong>Très bien</strong>. En dessous du premier seuil, la mention est « Passable » (dès 10/20). Les valeurs par défaut sont 12, 14 et 16.</p><h2 id="les-zones-de-rentabilite" tabindex="-1">Les zones de rentabilité <a class="header-anchor" href="#les-zones-de-rentabilite" aria-label="Permalink to &quot;Les zones de rentabilité&quot;">​</a></h2><p>Les seuils <strong>Viable</strong> et <strong>Confortable</strong> de chaque catégorie de programme (Parcours Métiers, Compétences Métiers, Technologies &amp; Outils), exprimés en inscriptions confirmées, entre 1 et 15. Le seuil Confortable doit être <strong>supérieur</strong> au seuil Viable. En dessous du seuil Viable, la cohorte est Fragile.</p><p>Un changement ne touche que les <strong>cohortes à venir</strong> : une cohorte qui a démarré garde la zone de son démarrage, et les rémunérations aussi.</p><h2 id="les-jours-feries" tabindex="-1">Les jours fériés <a class="header-anchor" href="#les-jours-feries" aria-label="Permalink to &quot;Les jours fériés&quot;">​</a></h2><p><strong>Administration → Jours fériés</strong> : ajoutez une date et son libellé, ou supprimez-la. Les délais de l&#39;admission se comptent en <strong>jours ouvrés</strong> (du lundi au vendredi) hors ces jours. <strong>Saisissez les fêtes mobiles chaque année.</strong> Les échéances déjà fixées gardent leur date.</p>',13)])])}const p=s(a,[["render",o]]);export{m as __pageData,p as default};
